//! Luau's limits for the serializer (DESIGN §3, §5.2 "Limit cases"), end to end on `tests/fixture_limits`
//! (generated by its `generate.cjs`): `Wide<N>` types with N string, `u8` and `Vector3` fields, and unions of 50 to 250
//! object members. Every `fitted` decision of the build is recorded with its probe chunks
//! (`flamework_rs::limits_record`), which this test compiles itself with Luau (`rbxts_luau_check`, at the load check's
//! levels):
//! - the compact build is kept exactly when the plain build fails with the margin (20) and the call's live locals as
//!   padding, except where neither fits with the margin and the plain build fits without it at the error levels;
//! - every output compiles at every level.
//!
//! The project is copied to a temporary directory with a `node_modules` as an install has it (`support::project`);
//! without the monorepo and the `@rbxts` packages the test is skipped, saying so. It is the only test of this binary:
//! the recording is process-wide.

#![cfg(windows)]

mod support;

use flamework_rs::Flamework;
use flamework_rs::limits_record::{self, Decision};
use rbxts_luau_check::{ROBLOX_LEVELS, Severity};
use support::project::{Project, assert_clean, luau};

const FIXTURE: &str = "fixture_limits";

/// Whether Luau compiles `source` at every level (`Severity::Error` levels only with `errors_only`); a refusal that
/// is not about a limit fails the test.
fn compiles(source: &str, errors_only: bool) -> bool {
    ROBLOX_LEVELS.iter().filter(|level| !errors_only || level.2 == Severity::Error).all(|&(o, d, _)| {
        match rbxts_luau_check::compile(source, o, d) {
            Ok(()) => true,
            Err(error) => {
                assert!(error.message.starts_with("Out of"), "not a limit: {error:?}\n{source}");
                false
            }
        }
    })
}

fn describe(decision: &Decision) -> String {
    format!(
        "{} (outer {}, plain locals {}, compact kept {})",
        decision.what.as_deref().unwrap_or("a call site"),
        decision.outer,
        decision.plain_locals,
        decision.kept_compact
    )
}

#[test]
fn compact_exactly_when_plain_does_not_fit() {
    let Some(project) = Project::new(FIXTURE, "limits") else { return };
    limits_record::start();
    let report = project.build_with(Flamework::new());
    let decisions = limits_record::take();
    assert_clean(&report);

    let mut compact = Vec::new();
    for decision in &decisions {
        let plain_fits = compiles(&decision.plain[0], false);
        if decision.kept_compact {
            assert!(!plain_fits, "compact, but plain fits with the margin: {}", describe(decision));
            compact.push(decision.what.clone().unwrap_or_default());
            let built = decision.compact.as_ref().expect("the compact build");
            if !compiles(&built[0], false) {
                // neither fits with the margin: plain does not fit without it, compact does
                assert!(!compiles(&decision.plain[1], true), "{}", describe(decision));
                assert!(compiles(&built[1], true), "{}", describe(decision));
            }
        } else if !plain_fits {
            // neither fits with the margin, and plain fits without it
            let built = decision.compact.as_ref().unwrap_or_else(|| panic!("no compact build: {}", describe(decision)));
            assert!(!compiles(&built[0], false), "{}", describe(decision));
            assert!(compiles(&decision.plain[1], true), "{}", describe(decision));
        }
    }

    // Where the thresholds fall (each type's hoisted s_/w_/r_ functions and its serializer's two): 40 fields fit
    // plainly; a string read holds three locals per field, so `r_Wide60` (183) is past the 180 kept to spare; the
    // writes (two per field) follow from 100 fields, the size functions (a sum over every field: registers) from 150,
    // `Vector3` reads (one per field) at 250; `u8` fields and the unions never come near.
    let kept = |name: &str| compact.iter().filter(|what| what.contains(&format!("'{name}'"))).count();
    let counts: Vec<usize> = ["Wide40", "Wide60", "Wide80", "Wide100", "Wide110", "Wide150", "Wide250", "Union250"]
        .iter()
        .map(|name| kept(name))
        .collect();
    assert_eq!(counts, [0, 1, 1, 2, 2, 3, 4, 0], "{compact:#?}");
    eprintln!("{} decisions recorded, compact kept for: {compact:#?}", decisions.len());

    // Every output loads where Roblox runs it, and with constant folding off.
    for file in ["strings.luau", "bytes.luau", "vectors.luau", "unions.luau"] {
        let source = luau(&report, file);
        for &(o, d, _) in ROBLOX_LEVELS {
            if let Err(error) = rbxts_luau_check::compile(source, o, d) {
                panic!("{file} does not compile at O{o} D{d}: {error:?}");
            }
        }
    }
}
